const item = $input.first().json.body || $input.first().json;

const incidentId = item.incidentId || item.id || `SOS-${Date.now().toString().slice(-4)}`;
const title = item.title || 'Emergency SOS Panic Triggered';
const category = item.category || 'SOS_PANIC'; // SOS_PANIC, FIRE_HAZARD, THEFT, PERIMETER_BREACH, MEDICAL, VANDALISM, SUSPICIOUS_ACTIVITY
const severity = item.severity || 'CRITICAL'; // CRITICAL, HIGH, MEDIUM, LOW
const flatNumber = item.flatNumber || 'Unknown Flat';
const tower = item.tower || 'General Society';
const location = item.location || `${tower} - Flat ${flatNumber}`;
const description = item.description || 'Resident triggered instant panic alert from mobile app';
const reportedByName = item.reportedByName || 'Resident / Security Guard';
const callerPhone = item.callerPhone || item.phone || 'N/A';
const evidencePhotos = item.evidencePhotos || [];

const prompt = `You are the Chief Emergency Response Commander and Crisis Triage AI for Mana Community Society.
An urgent security or safety incident has been triggered in the command center. Analyze the incident details immediately and formulate an emergency dispatch and containment plan.

Incident Telemetry:
- Incident ID: ${incidentId}
- Category: ${category}
- Assessed Severity: ${severity}
- Location: ${location} (${tower}, Flat ${flatNumber})
- Description: ${description}
- Reported By: ${reportedByName} (${callerPhone})
- Evidence Files Count: ${evidencePhotos.length}

Your Objectives:
1. Triage priority level (P1_LIFE_SAFETY, P2_PROPERTY_THREAT, P3_URGENT_INVESTIGATION, P4_ROUTINE).
2. Formulate immediate Security Guard on-ground deployment instructions (nearest gate guards, quick-response team).
3. Recommend external emergency services mobilization (Ambulance, Fire Brigade, Police Station 112) with trigger thresholds.
4. Draft immediate WhatsApp/SMS broadcast advisory for neighboring residents to keep hallways clear or stay indoors.
5. Provide a 4-step Incident Commander stabilization checklist.

Respond ONLY with a valid JSON object matching this exact schema:
{
  "incidentId": "${incidentId}",
  "priority": "P1_LIFE_SAFETY" | "P2_PROPERTY_THREAT" | "P3_URGENT_INVESTIGATION" | "P4_ROUTINE",
  "escalationLevel": "RED_ALERT" | "AMBER_ALERT" | "YELLOW_MONITOR",
  "externalServicesRequired": {
    "callPolice": boolean,
    "callAmbulance": boolean,
    "callFireBrigade": boolean,
    "justification": string
  },
  "guardDispatchRunbook": [
    "Step 1: Specific guard action",
    "Step 2: Specific containment action"
  ],
  "residentBroadcastMessage": "Short 2-sentence urgent advisory for society notification feed",
  "estimatedContainmentMinutes": number,
  "incidentCommanderChecklist": [
    "Checklist item 1",
    "Checklist item 2",
    "Checklist item 3",
    "Checklist item 4"
  ]
}`;

return [{
  json: {
    incidentId,
    prompt
  }
}];

const geminiResponse = $input.first().json;
const incidentId = $('Prepare Emergency Dispatch Prompt').first().json.incidentId;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  parsed = {
    incidentId: incidentId,
    priority: "P1_LIFE_SAFETY",
    escalationLevel: "RED_ALERT",
    externalServicesRequired: {
      callPolice: true,
      callAmbulance: false,
      callFireBrigade: false,
      justification: "Fallback safety rule: dispatch duty guards immediately to verify situation."
    },
    guardDispatchRunbook: [
      "Dispatch Main Gate Quick Response Team (QRT) to reported flat/tower immediately.",
      "CCTV control room lock and monitor elevators and entry/exit turnstiles.",
      "Establish two-way intercom contact with resident."
    ],
    residentBroadcastMessage: "Emergency response team is investigating an incident in your tower. Please cooperate with security guards and keep stairways accessible.",
    estimatedContainmentMinutes: 10,
    incidentCommanderChecklist: [
      "Verify guard arrival on ground",
      "Confirm resident safety via intercom",
      "Check CCTV camera feed for perimeter anomalies",
      "Document entry/exit logs during incident window"
    ]
  };
}

return [{
  json: {
    status: "success",
    dispatchedAt: new Date().toISOString(),
    dispatchPlan: parsed
  }
}];
